-- docs/expansion/reference-data.md. The rows are COPY blocks, as pg_dump writes them: psql loads the file as it
-- stands, and the tests' database through tests/Ehr.Testing/ReferenceData.cs. Tab-separated; \N is a null.
BEGIN;
CREATE TEMPORARY TABLE incoming_observation_codes (code text, display text, kind text, unit text, reference_low text, reference_high text, range_source text, copyright text) ON COMMIT DROP;
SELECT code, display, kind, unit, reference_low::numeric, reference_high::numeric, range_source, copyright FROM incoming_observation_codes
ON CONFLICT (code) DO UPDATE
    SET display = EXCLUDED.display, kind = EXCLUDED.kind, unit = EXCLUDED.unit, reference_low = EXCLUDED.reference_low, reference_high = EXCLUDED.reference_high, range_source = EXCLUDED.range_source, copyright = EXCLUDED.copyright
    WHERE (observation_codes.display, observation_codes.kind, observation_codes.unit, observation_codes.reference_low, observation_codes.reference_high, observation_codes.range_source, observation_codes.copyright)
        IS DISTINCT FROM (EXCLUDED.display, EXCLUDED.kind, EXCLUDED.unit, EXCLUDED.reference_low, EXCLUDED.reference_high, EXCLUDED.range_source, EXCLUDED.copyright);
DELETE FROM ehr.observation_codes t
WHERE NOT EXISTS (SELECT 1 FROM incoming_observation_codes i WHERE i.code = t.code);
CREATE TEMPORARY TABLE incoming_order_result_codes (catalog_code text, observation_code text) ON COMMIT DROP;
SELECT catalog_code, observation_code FROM incoming_order_result_codes
ON CONFLICT (catalog_code, observation_code) DO NOTHING;
DELETE FROM ehr.order_result_codes t
WHERE NOT EXISTS (SELECT 1 FROM incoming_order_result_codes i WHERE i.catalog_code = t.catalog_code AND i.observation_code = t.observation_code);
COMMIT;
